// Standards Question Bank: Algebra I (8th Accelerated). GENERATED by tools/stdbank/build.py from tools/stdbank/alg1.py.
// Do not hand-edit; change the .py file and build again. Standards codes are checked against data/standards.js.
// Fields: id, std (Alabama code), part (letter), q, a, lvl (1 on-ramp, 2 on level, 3 stretch), choices, also (other right answers), steps (Vault Raid step help).
export default {"cls": "8th-acc","label": "Algebra I (8th Accelerated)","items": [{"id": "AlgI.1-01","std": "Alg I.1","q": "Write 9^{{1/2}} another way and evaluate it.","a": "√9 = 3","lvl": 1,"also": ["3"],"steps": ["A power of {1/2} means square root: 9^{{1/2}} = √9.","What number times itself is 9?"]},{"id": "AlgI.1-02","std": "Alg I.1","q": "Evaluate: 8^{{1/3}}","a": "2","lvl": 1,"steps": ["A power of {1/3} means cube root: 8^{{1/3}} = ∛8.","What number times itself 3 times is 8?"]},{"id": "AlgI.1-03","std": "Alg I.1","q": "Evaluate: 16^{{3/4}}","a": "8","lvl": 2,"steps": ["Split the power: 16^{{3/4}} = (∜16)³.","Find ∜16: what number to the 4th power is 16?","Now cube that number."]},{"id": "AlgI.1-04","std": "Alg I.1","q": "Write ∛x as a power of x.","a": "x^{{1/3}}","lvl": 1,"also": ["x^(1/3)","x^1/3"],"steps": ["A cube root is the same as a power of {1/3}.","Write x with that power."]},{"id": "AlgI.1-05","std": "Alg I.1","q": "Why does 5^{{1/2}} = √5? Use (5^{{1/2}})².","a": "(5^{{1/2}})² = 5¹ = 5, so 5^{{1/2}} is the number whose square is 5","lvl": 3,"also": ["√5"],"steps": ["Power to a power: multiply the exponents.","{1/2} × 2 = 1, so (5^{{1/2}})² = 5¹ = 5.","So 5^{{1/2}} is a number whose square is 5. What other symbol means that?"]},{"id": "AlgI.1-06","std": "Alg I.1","q": "Evaluate: 27^{{2/3}}","a": "9","lvl": 2,"steps": ["Split the power: 27^{{2/3}} = (∛27)².","∛27 = 3, because 3 × 3 × 3 = 27.","Now square it."]},{"id": "AlgI.1-07","std": "Alg I.1","q": "Evaluate: 25^{−{1/2}}","a": "{1/5}","lvl": 3,"also": ["0.2"],"steps": ["A negative power means 1 over it: 25^{−{1/2}} = {1/√25}.","Find √25, then write the fraction."]},{"id": "AlgI.2-01","std": "Alg I.2","q": "Simplify: √50","a": "5√2","lvl": 1,"steps": ["Find the biggest perfect square that goes into 50: 25 × 2 = 50.","√50 = √25 × √2. Take √25."]},{"id": "AlgI.2-02","std": "Alg I.2","q": "Simplify: √72","a": "6√2","lvl": 2,"steps": ["Find the biggest perfect square that goes into 72: 36 × 2 = 72.","√72 = √36 × √2. Take √36."]},{"id": "AlgI.2-03","std": "Alg I.2","q": "Simplify: √(x⁶)","a": "x³","lvl": 2,"also": ["x^3"],"steps": ["A square root cuts the exponent in half.","What is half of 6?"]},{"id": "AlgI.2-04","std": "Alg I.2","q": "Write x^{{3/2}} as a radical.","a": "√(x³)","lvl": 2,"also": ["(√x)³","x√x"],"steps": ["The bottom of the fraction power is the root. A 2 means square root.","The top of the fraction power is the power inside the root."]},{"id": "AlgI.2-05","std": "Alg I.2","q": "Simplify: x^{{1/2}} · x^{{3/2}}","a": "x²","lvl": 2,"also": ["x^2"],"steps": ["Same base, multiplying: add the exponents.","{1/2} + {3/2} = {4/2}. Simplify."]},{"id": "AlgI.2-06","std": "Alg I.2","q": "Simplify: (x^{{2/3}})³","a": "x²","lvl": 2,"also": ["x^2"],"steps": ["Power to a power: multiply the exponents.","{2/3} × 3 = ?"]},{"id": "AlgI.2-07","std": "Alg I.2","q": "Simplify: √12 + √27","a": "5√3","lvl": 3,"steps": ["Simplify each root. √12 = √4 × √3 = 2√3.","√27 = √9 × √3 = 3√3.","Both are √3 terms. Add the numbers in front."]},{"id": "AlgI.2-08","std": "Alg I.2","q": "Simplify: ∛54","a": "3∛2","lvl": 3,"steps": ["Find the biggest perfect cube that goes into 54: 27 × 2 = 54.","∛54 = ∛27 × ∛2. Take ∛27."]},{"id": "AlgI.3-01","std": "Alg I.3","q": "What is i²?","a": "−1","lvl": 1,"steps": ["i means √(−1).","Squaring a square root undoes it. What is (√(−1))²?"]},{"id": "AlgI.3-02","std": "Alg I.3","q": "Write √(−25) using i.","a": "5i","lvl": 1,"steps": ["Split it: √(−25) = √25 × √(−1).","√(−1) = i. Find √25."]},{"id": "AlgI.3-03","std": "Alg I.3","q": "Write √(−7) using i.","a": "i√7","lvl": 2,"also": ["√7i","√7 i"],"steps": ["Split it: √(−7) = √7 × √(−1).","√(−1) = i. 7 isn't a perfect square, so √7 stays."]},{"id": "AlgI.3-04","std": "Alg I.3","q": "Simplify: i³","a": "−i","lvl": 2,"steps": ["Break it up: i³ = i² × i.","Use i² = −1, then multiply."]},{"id": "AlgI.3-05","std": "Alg I.3","q": "Simplify: i⁴","a": "1","lvl": 2,"steps": ["Break it up: i⁴ = i² × i².","Use i² = −1, then multiply."]},{"id": "AlgI.3-06","std": "Alg I.3","q": "Simplify: √(−36) + √(−4)","a": "8i","lvl": 3,"steps": ["Write each with i: √(−36) = 6i.","√(−4) = 2i. Add the like terms."]},{"id": "AlgI.3-07","std": "Alg I.3","q": "Is √(−9) a real number?","a": "No (it is 3i)","lvl": 1,"also": ["no"],"steps": ["No real number times itself gives a negative.","√(−9) = 3i. Is i a real number?"]},{"id": "AlgI.4-01","std": "Alg I.4","q": "In 1,000(1.05)^t, what does 1.05 mean?","a": "The amount grows 5% each year","lvl": 1,"also": ["5% growth"],"steps": ["In a(b)^{t}, b is what you multiply by each year.","1.05 = 1 + 0.05. Write 0.05 as a percent. Is it growing or shrinking?"]},{"id": "AlgI.4-02","std": "Alg I.4","q": "In 1,000(1.05)^t, what does 1,000 mean?","a": "The starting amount","lvl": 1,"also": ["initial amount","starting value"],"steps": ["Put t = 0: 1,000(1.05)⁰ = 1,000 × 1.","So 1,000 is the amount at time 0. What is that called?"]},{"id": "AlgI.4-03","std": "Alg I.4","q": "A phone plan costs 25 + 0.10t for t texts. What does 0.10 mean?","a": "§0.10 per text","lvl": 1,"also": ["10 cents per text"],"steps": ["In 25 + 0.10t, the 0.10 is multiplied by t, the number of texts.","So each text adds how much?"]},{"id": "AlgI.4-04","std": "Alg I.4","q": "In 500(0.8)^t, is the amount growing or decaying? By what percent?","a": "Decaying by 20% each period","lvl": 2,"also": ["decay 20%","decaying"],"steps": ["0.8 is less than 1, so you keep less each period. Growing or decaying?","Find the part lost: 1 − 0.8 = 0.2. Write 0.2 as a percent."]},{"id": "AlgI.4-05","std": "Alg I.4","q": "The area of a garden is (x + 3)(x + 2). What do x + 3 and x + 2 stand for?","a": "The length and width","lvl": 2,"also": ["length and width"],"steps": ["Area of a rectangle = length × width.","So what do the two factors stand for?"]},{"id": "AlgI.4-06","std": "Alg I.4","q": "h = −16t² + 64t + 5 gives a ball's height. What does 5 mean?","a": "The ball starts 5 ft above the ground","lvl": 2,"also": ["starting height","5 ft"],"steps": ["Put t = 0 for the start: h = −16(0)² + 64(0) + 5.","So 5 is the height at the very start. Where is the ball then?"]},{"id": "AlgI.4-07","std": "Alg I.4","q": "P(1 + r)^t: if r = 0.03, what is the growth factor?","a": "1.03","lvl": 2,"steps": ["The growth factor is 1 + r.","Put in r = 0.03."]},{"id": "AlgI.5-01","std": "Alg I.5","q": "Factor: x² − 49","a": "(x + 7)(x − 7)","lvl": 1,"also": ["(x − 7)(x + 7)"],"steps": ["This is a difference of squares: a² − b² = (a + b)(a − b).","x² is x squared and 49 is 7². So a = x and b = 7."]},{"id": "AlgI.5-02","std": "Alg I.5","q": "Factor: x⁴ − 16 completely.","a": "(x² + 4)(x + 2)(x − 2)","lvl": 3,"steps": ["x⁴ = (x²)² and 16 = 4². So x⁴ − 16 = (x² + 4)(x² − 4).","x² − 4 is a difference of squares too. Factor it again.","x² + 4 doesn't factor with real numbers. Keep it as it is."]},{"id": "AlgI.5-03","std": "Alg I.5","q": "Factor: 4x² − 9","a": "(2x + 3)(2x − 3)","lvl": 2,"also": ["(2x − 3)(2x + 3)"],"steps": ["4x² = (2x)² and 9 = 3².","Use a² − b² = (a + b)(a − b) with a = 2x and b = 3."]},{"id": "AlgI.5-04","std": "Alg I.5","q": "Rewrite x² + 6x + 9 as a square.","a": "(x + 3)²","lvl": 2,"steps": ["9 is a perfect square: 9 = 3².","Check the middle: 2 × x × 3 = 6x. So it's (x + ?)²."]},{"id": "AlgI.5-05","std": "Alg I.5","q": "Factor out the GCF: 6x³ + 9x²","a": "3x²(2x + 3)","lvl": 1,"steps": ["The GCF of 6 and 9 is 3. The GCF of x³ and x² is x².","Pull out 3x²: divide each term by 3x²."]},{"id": "AlgI.5-06","std": "Alg I.5","q": "Find 51² − 49² using a difference of squares.","a": "200","lvl": 3,"steps": ["Use a² − b² = (a + b)(a − b) with a = 51 and b = 49.","51 + 49 = 100 and 51 − 49 = 2. Multiply."]},{"id": "AlgI.5-07","std": "Alg I.5","q": "Factor: x² − 10x + 25","a": "(x − 5)²","lvl": 2,"steps": ["25 is a perfect square: 25 = 5². Check the middle: 2 × x × 5 = 10x.","The middle term is minus, so it's (x − ?)²."]},{"id": "AlgI.6-01","std": "Alg I.6","q": "Factor y = x² − 5x + 6 to find the zeros.","a": "x = 2 and x = 3","lvl": 2,"also": ["2, 3","2 and 3"],"steps": ["Find two numbers that multiply to 6 and add to −5: −2 and −3.","So y = (x − 2)(x − 3). Set each factor equal to 0."]},{"id": "AlgI.6-02","std": "Alg I.6","q": "Complete the square: y = x² + 4x + 1. What is the vertex?","a": "(−2, −3)","lvl": 3,"steps": ["Half of 4 is 2, and 2² = 4. Add and subtract 4: y = x² + 4x + 4 − 4 + 1.","Now it's y = (x + 2)² − 3.","In y = (x − h)² + k the vertex is (h, k). x + 2 means h = −2."]},{"id": "AlgI.6-03","std": "Alg I.6","q": "y = (x − 3)² + 4. What is the minimum value?","a": "4","lvl": 1,"steps": ["(x − 3)² is never negative. Its smallest value is 0.","When (x − 3)² = 0, what is y?"]},{"id": "AlgI.6-04","std": "Alg I.6","q": "Rewrite 1.2^t as a monthly rate: 1.2^t = (1.2^{{1/12}})^{12t}. About what is the monthly growth factor? Round to 3 decimals.","a": "1.015","lvl": 3,"steps": ["The monthly factor is 1.2^{{1/12}}, the 12th root of 1.2.","On a calculator, type 1.2, the power key, then (1 ÷ 12). Round to 3 decimals."]},{"id": "AlgI.6-05","std": "Alg I.6","q": "y = (x + 1)(x − 7). Where is the axis of symmetry?","a": "x = 3","lvl": 2,"steps": ["The zeros are where each factor is 0: x = −1 and x = 7.","The axis of symmetry is halfway between the zeros: (−1 + 7) ÷ 2."]},{"id": "AlgI.6-06","std": "Alg I.6","q": "Which form shows the zeros of a quadratic: standard, vertex, or factored?","a": "Factored","lvl": 1,"choices": ["Standard","Vertex","Factored"],"steps": ["Factored form looks like y = a(x − p)(x − q).","Setting each factor to 0 gives the zeros. Which form lets you read them right away?"]},{"id": "AlgI.6-07","std": "Alg I.6","q": "Which form shows the vertex of a quadratic: standard, vertex, or factored?","a": "Vertex","lvl": 1,"choices": ["Standard","Vertex","Factored"],"steps": ["Vertex form looks like y = a(x − h)² + k.","In that form you can read (h, k) right off. Which form is that?"]},{"id": "AlgI.6-08","std": "Alg I.6","q": "Find the zeros of y = x² + 2x − 15 by factoring.","a": "x = −5 and x = 3","lvl": 2,"also": ["−5, 3","−5 and 3"],"steps": ["Find two numbers that multiply to −15 and add to 2: 5 and −3.","So y = (x + 5)(x − 3). Set each factor equal to 0."]},{"id": "AlgI.7-01","std": "Alg I.7","q": "Add: (3x² + 2x − 5) + (x² − 4x + 7)","a": "4x² − 2x + 2","lvl": 1,"steps": ["Group like terms: (3x² + x²) + (2x − 4x) + (−5 + 7).","Add each group."]},{"id": "AlgI.7-02","std": "Alg I.7","q": "Subtract: (5x² − 3x + 1) − (2x² + x − 4)","a": "3x² − 4x + 5","lvl": 2,"steps": ["The minus goes to every term in the second group: 5x² − 3x + 1 − 2x² − x + 4.","Group like terms and combine."]},{"id": "AlgI.7-03","std": "Alg I.7","q": "Multiply: (x + 4)(x − 2)","a": "x² + 2x − 8","lvl": 1,"steps": ["Multiply each term by each term: x · x, x · (−2), 4 · x, 4 · (−2).","That gives x² − 2x + 4x − 8. Combine the x terms."]},{"id": "AlgI.7-04","std": "Alg I.7","q": "Multiply: (2x − 3)(x + 5)","a": "2x² + 7x − 15","lvl": 2,"steps": ["Multiply each term by each term: 2x · x, 2x · 5, −3 · x, −3 · 5.","That gives 2x² + 10x − 3x − 15. Combine the x terms."]},{"id": "AlgI.7-05","std": "Alg I.7","q": "Multiply: (x − 6)²","a": "x² − 12x + 36","lvl": 2,"steps": ["Write it twice: (x − 6)(x − 6).","Multiply each pair: x² − 6x − 6x + 36. Combine the x terms."]},{"id": "AlgI.7-06","std": "Alg I.7","q": "Multiply: 3x(x² − 2x + 4)","a": "3x³ − 6x² + 12x","lvl": 1,"steps": ["Multiply 3x by each term: 3x · x², 3x · (−2x), 3x · 4.","Same base, multiplying: add the exponents. x · x² = x³."]},{"id": "AlgI.7-07","std": "Alg I.7","q": "Multiply: (x + 1)(x² − x + 1)","a": "x³ + 1","lvl": 3,"steps": ["Multiply x by each term: x³ − x² + x.","Multiply 1 by each term: x² − x + 1.","Add the two rows. Some terms cancel."]},{"id": "AlgI.7-08","std": "Alg I.7","q": "Is the product of two polynomials always a polynomial?","a": "Yes (polynomials are closed under multiplication)","lvl": 2,"choices": ["Yes (polynomials are closed under multiplication)","No"],"steps": ["Multiplying polynomials gives terms like a number times x to a whole-number power.","Can that ever make a negative or fraction exponent?"]},{"id": "AlgI.7-09","std": "Alg I.7","q": "What is the degree of 4x³ − x⁵ + 2?","a": "5","lvl": 1,"steps": ["The degree is the highest exponent.","Look at every term: 4x³, −x⁵ and 2. Which exponent is biggest?"]},{"id": "AlgI.8-01","std": "Alg I.8","q": "Solve: |x − 3| = 7","a": "x = 10 or x = −4","lvl": 1,"also": ["10, −4","−4, 10"],"steps": ["The inside is 7 or −7: x − 3 = 7 or x − 3 = −7.","Add 3 to both sides of each."]},{"id": "AlgI.8-02","std": "Alg I.8","q": "Solve: |2x + 1| = 9","a": "x = 4 or x = −5","lvl": 2,"also": ["4, −5","−5, 4"],"steps": ["The inside is 9 or −9: 2x + 1 = 9 or 2x + 1 = −9.","Subtract 1, then divide by 2, in each one."]},{"id": "AlgI.8-03","std": "Alg I.8","q": "Solve: |x + 5| = −2","a": "No solution (an absolute value cannot be negative)","lvl": 1,"also": ["no solution"],"steps": ["An absolute value is a distance from 0.","Can a distance be negative?"]},{"id": "AlgI.8-04","std": "Alg I.8","q": "Solve: |x| + 4 = 10","a": "x = 6 or x = −6","lvl": 1,"also": ["±6"],"steps": ["Get the absolute value alone: subtract 4. Now |x| = 6.","Which numbers are 6 away from 0?"]},{"id": "AlgI.8-05","std": "Alg I.8","q": "Solve and check: |x − 1| = 2x + 4","a": "x = −1 (x = −5 is extraneous)","lvl": 3,"also": ["−1","x = −1"],"steps": ["Case 1: x − 1 = 2x + 4. That gives x = −5.","Case 2: x − 1 = −(2x + 4). That gives 3x = −3, so x = −1.","Check x = −5: |−6| = 6, but 2(−5) + 4 = −6. Does it work?"]},{"id": "AlgI.8-06","std": "Alg I.8","q": "Why must you check answers to |x + 2| = x − 4?","a": "Splitting into two cases can give a value that makes x − 4 negative, and an absolute value cannot equal a negative number, so that value is extraneous","lvl": 2,"steps": ["Try the case x + 2 = −(x − 4). That gives x = 1.","Put x = 1 back in: |1 + 2| = 3, but 1 − 4 = −3.","Can an absolute value equal a negative number?"]},{"id": "AlgI.8-07","std": "Alg I.8","q": "Solve and check: |3x| = x + 8","a": "x = 4 or x = −2","lvl": 3,"also": ["4, −2","−2, 4"],"steps": ["Case 1: 3x = x + 8. Solve for x.","Case 2: 3x = −(x + 8), so 4x = −8. Solve for x.","Check both in |3x| = x + 8."]},{"id": "AlgI.9-01","std": "Alg I.9","q": "Solve by inspection: x² = 49","a": "x = ±7","lvl": 1,"part": "b","also": ["±7","7 and −7"],"steps": ["What number squared is 49?","A negative number squared is positive too. Use ±."]},{"id": "AlgI.9-02","std": "Alg I.9","q": "Solve: (x − 2)² = 25","a": "x = 7 or x = −3","lvl": 2,"part": "b","also": ["7, −3","−3, 7"],"steps": ["Take the square root of both sides: x − 2 = 5 or x − 2 = −5.","Add 2 to each."]},{"id": "AlgI.9-03","std": "Alg I.9","q": "Solve by factoring: x² + 5x + 6 = 0","a": "x = −2 or x = −3","lvl": 2,"part": "b","also": ["−2, −3","−3, −2"],"steps": ["Find two numbers that multiply to 6 and add to 5: 2 and 3.","So (x + 2)(x + 3) = 0. Set each factor equal to 0."]},{"id": "AlgI.9-04","std": "Alg I.9","q": "Solve: x² − 4x − 12 = 0","a": "x = 6 or x = −2","lvl": 2,"part": "b","also": ["6, −2","−2, 6"],"steps": ["Find two numbers that multiply to −12 and add to −4: −6 and 2.","So (x − 6)(x + 2) = 0. Set each factor equal to 0."]},{"id": "AlgI.9-05","std": "Alg I.9","q": "Complete the square: x² + 6x = 7. Write it as (x + p)² = q.","a": "(x + 3)² = 16","lvl": 2,"part": "a","steps": ["Half of 6 is 3, and 3² = 9.","Add 9 to both sides: x² + 6x + 9 = 16.","The left side is a perfect square: (x + ?)²."]},{"id": "AlgI.9-06","std": "Alg I.9","q": "Complete the square to solve: x² − 8x + 3 = 0","a": "x = 4 ± √13","lvl": 3,"part": "a","also": ["4 ± √13"],"steps": ["Move the 3: x² − 8x = −3.","Half of −8 is −4, and (−4)² = 16. Add 16 to both sides: (x − 4)² = 13.","Take the square root of both sides, then add 4."]},{"id": "AlgI.9-07","std": "Alg I.9","q": "Solve with the quadratic formula: 2x² + 3x − 2 = 0","a": "x = {1/2} or x = −2","lvl": 3,"part": "b","also": ["1/2, −2","0.5, −2"],"steps": ["a = 2, b = 3, c = −2. Use x = {−b ± √(b² − 4ac)/2a}.","b² − 4ac = 9 − 4(2)(−2) = 25, and √25 = 5.","x = {−3 ± 5/4}. Find one answer with + and one with −."]},{"id": "AlgI.9-08","std": "Alg I.9","q": "Solve: x² + 9 = 0","a": "x = ±3i (no real solutions)","lvl": 3,"part": "b","also": ["±3i","no real solution"],"steps": ["Subtract 9: x² = −9.","Take the square root: x = ±√(−9). Use √(−1) = i."]},{"id": "AlgI.9-09","std": "Alg I.9","q": "What is the discriminant of x² + 2x + 5? How many real solutions?","a": "−16; no real solutions","lvl": 3,"part": "b","also": ["−16"],"steps": ["The discriminant is b² − 4ac. Here a = 1, b = 2, c = 5.","2² − 4(1)(5) = 4 − 20.","A negative discriminant means no real solutions."]},{"id": "AlgI.9-10","std": "Alg I.9","q": "Solve: 3x² = 48","a": "x = ±4","lvl": 1,"part": "b","also": ["±4"],"steps": ["Divide both sides by 3: x² = 16.","Take the square root. Remember ±."]},{"id": "AlgI.10-01","std": "Alg I.10","q": "Solve by elimination: x + y = 10 and x − y = 4","a": "(7, 3)","lvl": 1,"part": "a","steps": ["Add the equations. The y's cancel: 2x = 14.","Solve for x, then put it into x + y = 10."]},{"id": "AlgI.10-02","std": "Alg I.10","q": "Solve by elimination: 2x + 3y = 12 and 2x − y = 4","a": "(3, 2)","lvl": 2,"part": "a","steps": ["Subtract the second equation from the first. The 2x's cancel: 4y = 8.","Solve for y, then put it into 2x − y = 4."]},{"id": "AlgI.10-03","std": "Alg I.10","q": "Solve: 3x + 2y = 16 and x − 2y = 0","a": "(4, 2)","lvl": 2,"part": "a","steps": ["Add the equations. The 2y's cancel: 4x = 16.","Solve for x, then put it into x − 2y = 0."]},{"id": "AlgI.10-04","std": "Alg I.10","q": "Solve: 4x + 3y = 5 and 2x + y = 1","a": "(−1, 3)","lvl": 3,"part": "a","steps": ["Multiply the second equation by 2: 4x + 2y = 2.","Subtract it from the first: y = 3.","Put y = 3 into 2x + y = 1 and solve for x."]},{"id": "AlgI.10-05","std": "Alg I.10","q": "Which method is faster for y = 3x − 1 and 2x + y = 9: substitution or elimination?","a": "Substitution (y is already alone)","lvl": 1,"part": "a","also": ["substitution"],"steps": ["Look at y = 3x − 1. Is y already by itself?","When a letter is alone, you can put it right into the other equation. Which method does that?"]},{"id": "AlgI.10-06","std": "Alg I.10","q": "Solve y = 3x − 1 and 2x + y = 9.","a": "(2, 5)","lvl": 2,"part": "a","steps": ["y is alone, so substitute: 2x + (3x − 1) = 9.","Combine: 5x − 1 = 9. Solve for x.","Put x into y = 3x − 1. Write it as (x, y)."]},{"id": "AlgI.10-07","std": "Alg I.10","q": "A table for y = 2x + 1 and y = −x + 7 shows the same y at x = 2. What is the solution?","a": "(2, 5)","lvl": 2,"part": "b","steps": ["At x = 2, both give y = 2(2) + 1.","The solution is where both have the same x and y. Write it as (x, y)."]},{"id": "AlgI.10-08","std": "Alg I.10","q": "Elimination gives 0 = 6. What does that mean?","a": "No solution","lvl": 2,"part": "b","choices": ["One solution","No solution","Infinitely many solutions"],"steps": ["0 = 6 is never true.","If no x and y make it true, how many solutions are there?"]},{"id": "AlgI.11-01","std": "Alg I.11","q": "You have §60 and spend §4 a day. Write and solve an inequality for the days d until you have less than §20.","a": "60 − 4d < 20, so d > 10","lvl": 2,"also": ["d > 10"],"steps": ["Start at 60 and take away 4 each day: 60 − 4d.","Less than 20: 60 − 4d < 20.","Subtract 60: −4d < −40. Dividing by a negative flips the sign."]},{"id": "AlgI.11-02","std": "Alg I.11","q": "Solve: 3x − 7 ≥ 11","a": "x ≥ 6","lvl": 1,"steps": ["Add 7 to both sides: 3x ≥ 18.","Divide both sides by 3."]},{"id": "AlgI.11-03","std": "Alg I.11","q": "Solve: −2x + 5 < 13","a": "x > −4","lvl": 1,"steps": ["Subtract 5 from both sides: −2x < 8.","Divide by −2. Dividing by a negative flips the sign."]},{"id": "AlgI.11-04","std": "Alg I.11","q": "Solve: −3 ≤ 2x + 1 < 9","a": "−2 ≤ x < 4","lvl": 2,"steps": ["Do the same thing to all three parts. Subtract 1: −4 ≤ 2x < 8.","Divide all three parts by 2."]},{"id": "AlgI.11-05","std": "Alg I.11","q": "Solve: |x − 4| < 3","a": "1 < x < 7","lvl": 2,"steps": ["Less than means between: −3 < x − 4 < 3.","Add 4 to all three parts."]},{"id": "AlgI.11-06","std": "Alg I.11","q": "Solve: |x + 2| ≥ 5","a": "x ≤ −7 or x ≥ 3","lvl": 3,"steps": ["Greater than means outside: x + 2 ≤ −5 or x + 2 ≥ 5.","Subtract 2 from each."]},{"id": "AlgI.11-07","std": "Alg I.11","q": "A rectangle's length is 3 more than its width. Its area is 40. Write and solve an equation for the width.","a": "w(w + 3) = 40, w = 5","lvl": 3,"also": ["5","w = 5"],"steps": ["The width is w, so the length is w + 3. Area: w(w + 3) = 40.","Expand: w² + 3w − 40 = 0. Factor: (w + 8)(w − 5) = 0.","A width can't be negative. Which one works?"]},{"id": "AlgI.11-08","std": "Alg I.11","q": "A population of 200 doubles every year. Write an equation for when it reaches 3,200 and solve it.","a": "200 · 2^t = 3,200, t = 4 years","lvl": 3,"also": ["4","t = 4"],"steps": ["Doubling each year: 200 · 2^{t} = 3,200.","Divide both sides by 200: 2^{t} = 16.","What power of 2 is 16? Count: 2, 4, 8, 16."]},{"id": "AlgI.11-09","std": "Alg I.11","q": "Your test scores are 82 and 91. What score x on the 3rd test gives an average of at least 88?","a": "x ≥ 91","lvl": 2,"also": ["91"],"steps": ["Average of 3 tests: {82 + 91 + x/3} ≥ 88.","Multiply both sides by 3: 173 + x ≥ 264.","Subtract 173 from both sides."]},{"id": "AlgI.12-01","std": "Alg I.12","q": "Hot dogs cost §3 and drinks cost §2. You spend §24. Write an equation.","a": "3h + 2d = 24","lvl": 1,"steps": ["Each hot dog is §3, so h hot dogs cost 3h.","Each drink is §2, so d drinks cost 2d. Together they equal 24."]},{"id": "AlgI.12-02","std": "Alg I.12","q": "A plant is 4 cm tall and grows 1.5 cm a week. Write an equation for height h after w weeks.","a": "h = 1.5w + 4","lvl": 1,"steps": ["It grows 1.5 cm each week, so after w weeks it grew 1.5w.","Add the starting height, 4 cm."]},{"id": "AlgI.12-03","std": "Alg I.12","q": "A car worth §20,000 loses 15% of its value each year. Write an equation for its value v after t years.","a": "v = 20,000(0.85)^t","lvl": 2,"also": ["v = 20000(0.85)^t"],"steps": ["Losing 15% means you keep 85% each year: 1 − 0.15 = 0.85.","Start at 20,000 and multiply by 0.85 each year. Use t as the power."]},{"id": "AlgI.12-04","std": "Alg I.12","q": "Using 3h + 2d = 24, if you buy 4 hot dogs, how many drinks?","a": "6","lvl": 1,"steps": ["Put h = 4 in: 3(4) + 2d = 24, so 12 + 2d = 24.","Subtract 12, then divide by 2."]},{"id": "AlgI.12-05","std": "Alg I.12","q": "A ball's height is h = −16t² + 48t. When does it land?","a": "t = 3 seconds","lvl": 3,"also": ["3"],"steps": ["It lands when h = 0: −16t² + 48t = 0.","Factor: −16t(t − 3) = 0. Set each factor to 0.","t = 0 is when it's thrown. Which time is the landing?"]},{"id": "AlgI.12-06","std": "Alg I.12","q": "Using v = 20,000(0.85)^t, predict the value after 2 years.","a": "§14,450.00","lvl": 2,"also": ["14450","14,450"],"steps": ["Put t = 2 in: v = 20,000(0.85)².","0.85² = 0.7225. Multiply by 20,000."]},{"id": "AlgI.12-07","std": "Alg I.12","q": "When you graph h = 1.5w + 4, what labels go on the axes?","a": "Weeks on the x-axis, height in cm on the y-axis","lvl": 1,"steps": ["The input goes on the x-axis. Here the input is w, the weeks.","The output goes on the y-axis. What is the output, and what is its unit?"]},{"id": "AlgI.13-01","std": "Alg I.13","q": "You can spend at most §50 on shirts (§10) and hats (§5). Write the constraint.","a": "10s + 5h ≤ 50","lvl": 1,"steps": ["Shirts cost §10 each: 10s. Hats cost §5 each: 5h.","At most §50 means the total is less than or equal to 50."]},{"id": "AlgI.13-02","std": "Alg I.13","q": "Using 10s + 5h ≤ 50, is buying 3 shirts and 5 hats viable?","a": "No (§55 is over §50)","lvl": 2,"also": ["no"],"steps": ["Put s = 3 and h = 5 in: 10(3) + 5(5).","Is the total less than or equal to 50?"]},{"id": "AlgI.13-03","std": "Alg I.13","q": "Using 10s + 5h ≤ 50, is (2.5, 4) a viable answer?","a": "No (you cannot buy half a shirt)","lvl": 2,"also": ["no"],"steps": ["(2.5, 4) means 2.5 shirts and 4 hats.","Can you buy half of a shirt?"]},{"id": "AlgI.13-04","std": "Alg I.13","q": "A system: x + y ≤ 8, x ≥ 2, y ≥ 0. Is (3, 4) a solution?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Use x = 3 and y = 4. Check x + y ≤ 8: 3 + 4 = 7.","Check x ≥ 2 and y ≥ 0.","A solution has to make all three true. Does it?"]},{"id": "AlgI.13-05","std": "Alg I.13","q": "A system: x + y ≤ 8, x ≥ 2, y ≥ 0. Is (1, 5) a solution?","a": "No (x must be at least 2)","lvl": 1,"also": ["no"],"steps": ["Check x ≥ 2 with x = 1.","A solution has to make every inequality true."]},{"id": "AlgI.13-06","std": "Alg I.13","q": "Solve the system: y = x² and y = 4","a": "(2, 4) and (−2, 4)","lvl": 3,"steps": ["Both equal y, so set them equal: x² = 4.","x = 2 or x = −2. Find y for each, then write both points."]},{"id": "AlgI.13-07","std": "Alg I.13","q": "A field trip needs at least 60 seats. Vans hold 8 and cars hold 4. Write the constraint.","a": "8v + 4c ≥ 60","lvl": 2,"steps": ["Vans hold 8 each: 8v. Cars hold 4 each: 4c.","At least 60 means the seats are greater than or equal to 60."]},{"id": "AlgI.13-08","std": "Alg I.13","q": "In a problem about tickets sold, is −3 a viable solution?","a": "No (you cannot sell negative tickets)","lvl": 1,"also": ["no"],"steps": ["−3 would mean selling −3 tickets.","Can you sell a negative number of tickets?"]},{"id": "AlgI.14-01","std": "Alg I.14","q": "Is (2, 7) on the graph of y = 3x + 1?","a": "Yes (3(2) + 1 = 7)","lvl": 1,"also": ["yes"],"steps": ["Put x = 2 in: y = 3(2) + 1.","Does it give y = 7?"]},{"id": "AlgI.14-02","std": "Alg I.14","q": "Is (−1, 3) on the graph of y = x² + 1?","a": "No (y would be 2)","lvl": 1,"also": ["no"],"steps": ["Put x = −1 in: y = (−1)² + 1.","Does it give y = 3?"]},{"id": "AlgI.14-03","std": "Alg I.14","q": "The graph of 2x + y = 6 crosses the y-axis where?","a": "(0, 6)","lvl": 1,"steps": ["On the y-axis, x = 0. Put it in: 2(0) + y = 6.","Solve for y. Write it as a point."]},{"id": "AlgI.14-04","std": "Alg I.14","q": "Find k so that (3, k) is on the graph of y = 2x − 5.","a": "k = 1","lvl": 2,"steps": ["Put x = 3 in: k = 2(3) − 5.","Multiply, then subtract."]},{"id": "AlgI.14-05","std": "Alg I.14","q": "What does the graph of an equation in two variables show?","a": "Every solution (x, y) of the equation","lvl": 1,"steps": ["Each point on the graph is an (x, y) pair.","Does every point on the graph make the equation true?"]},{"id": "AlgI.14-06","std": "Alg I.14","q": "Is (4, −2) on the graph of y = |x − 6|?","a": "No (y would be 2)","lvl": 2,"also": ["no"],"steps": ["Put x = 4 in: y = |4 − 6| = |−2|.","An absolute value is never negative. Can it equal −2?"]},{"id": "AlgI.14-07","std": "Alg I.14","q": "Find the x-intercept of 3x − 4y = 12.","a": "(4, 0)","lvl": 2,"steps": ["On the x-axis, y = 0. Put it in: 3x − 4(0) = 12.","Solve for x. Write it as a point."]},{"id": "AlgI.15-01","std": "Alg I.15","q": "f(x) = 2x² − 3. Find f(−2).","a": "5","lvl": 1,"steps": ["Put −2 in for x: f(−2) = 2(−2)² − 3.","Square first: (−2)² = 4. Then multiply by 2 and subtract 3."]},{"id": "AlgI.15-02","std": "Alg I.15","q": "f(x) = 3(2)^x. Find f(3).","a": "24","lvl": 1,"steps": ["Put 3 in for x: f(3) = 3(2)³.","Do the power first: 2³ = 8. Then multiply by 3."]},{"id": "AlgI.15-03","std": "Alg I.15","q": "f(x) = |x − 5|. Find f(1).","a": "4","lvl": 1,"steps": ["Put 1 in for x: f(1) = |1 − 5| = |−4|.","Absolute value is the distance from 0."]},{"id": "AlgI.15-04","std": "Alg I.15","q": "f(x) = 4x − 7. Solve f(x) = 13.","a": "x = 5","lvl": 2,"steps": ["Set 4x − 7 = 13.","Add 7, then divide by 4."]},{"id": "AlgI.15-05","std": "Alg I.15","q": "C(n) = 15n + 40 is the cost of n people at a party. What does C(10) = 190 mean?","a": "10 people cost §190","lvl": 2,"steps": ["C(10) means n = 10 people.","190 is the cost C. Put that in words."]},{"id": "AlgI.15-06","std": "Alg I.15","q": "What is the domain of {(1, 3), (2, 5), (4, 3)}?","a": "{1, 2, 4}","lvl": 1,"steps": ["The domain is the inputs, the x-values.","Read the first number from each pair. List each one once."]},{"id": "AlgI.15-07","std": "Alg I.15","q": "What is the range of {(1, 3), (2, 5), (4, 3)}?","a": "{3, 5}","lvl": 1,"steps": ["The range is the outputs, the y-values.","Read the second number from each pair. List each one once."]},{"id": "AlgI.15-08","std": "Alg I.15","q": "A function gives the height of a ball for 0 ≤ t ≤ 4 seconds. What is a sensible domain?","a": "0 ≤ t ≤ 4","lvl": 2,"steps": ["The height is only known from t = 0 to t = 4.","Write that as an inequality for t."]},{"id": "AlgI.15-09","std": "Alg I.15","q": "What is the range of f(x) = x² + 2?","a": "y ≥ 2","lvl": 3,"also": ["f(x) ≥ 2"],"steps": ["x² is never negative. Its smallest value is 0.","So the smallest x² + 2 can be is 0 + 2. Can it go higher?"]},{"id": "AlgI.16-01","std": "Alg I.16","q": "Is y = 3x − 2 a function?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A function gives each x exactly one y.","Put any x into 3x − 2. Do you ever get two answers?"]},{"id": "AlgI.16-02","std": "Alg I.16","q": "Is x² + y² = 25 a function?","a": "No (most x values have two y values)","lvl": 2,"also": ["no"],"steps": ["Try x = 0: y² = 25, so y = 5 or y = −5.","One input with two outputs. Is that a function?"]},{"id": "AlgI.16-03","std": "Alg I.16","q": "Table x: 1, 2, 3, 1 and y: 5, 6, 7, 8. Function or not?","a": "Not a function (x = 1 has two outputs)","lvl": 1,"also": ["no","not a function"],"steps": ["Look for an x that shows up twice.","x = 1 goes with y = 5 and y = 8. Is that allowed in a function?"]},{"id": "AlgI.16-04","std": "Alg I.16","q": "Is y = |x| a function?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Put any x in. |x| gives one value.","Does any x give two outputs?"]},{"id": "AlgI.16-05","std": "Alg I.16","q": "Is x = 4 (a vertical line) a function?","a": "No","lvl": 2,"choices": ["Yes","No"],"steps": ["On x = 4 the points are (4, 0), (4, 1), (4, 2) and so on.","One input with many outputs. Use the vertical line test."]},{"id": "AlgI.16-06","std": "Alg I.16","q": "Every function is a relation. Is every relation a function?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["A relation is any set of pairs. A function has one output for each input.","Can a relation have one input with two outputs? Is that a function?"]},{"id": "AlgI.16-07","std": "Alg I.16","q": "Is y² = x a function of x?","a": "No","lvl": 3,"choices": ["Yes","No"],"steps": ["Try x = 4: y² = 4, so y = 2 or y = −2.","One input with two outputs. Is that a function?"]},{"id": "AlgI.17-01","std": "Alg I.17","q": "f(x) = 2x + 3 and g(x) = x². Find (f + g)(2).","a": "11","lvl": 1,"part": "a","steps": ["(f + g)(2) = f(2) + g(2).","f(2) = 2(2) + 3 and g(2) = 2². Add them."]},{"id": "AlgI.17-02","std": "Alg I.17","q": "f(x) = 2x + 3 and g(x) = x². Find (f − g)(3).","a": "0","lvl": 2,"part": "a","steps": ["(f − g)(3) = f(3) − g(3).","f(3) = 2(3) + 3 and g(3) = 3². Subtract."]},{"id": "AlgI.17-03","std": "Alg I.17","q": "f(x) = 2x + 3 and g(x) = x². Find f(g(2)).","a": "11","lvl": 2,"part": "b","steps": ["Work from the inside out. g(2) = 2² = 4.","Now find f(4) = 2(4) + 3."]},{"id": "AlgI.17-04","std": "Alg I.17","q": "f(x) = 2x + 3 and g(x) = x². Find g(f(2)).","a": "49","lvl": 2,"part": "b","steps": ["Work from the inside out. f(2) = 2(2) + 3 = 7.","Now find g(7) = 7²."]},{"id": "AlgI.17-05","std": "Alg I.17","q": "Water flows in at 5 gal per min: I(t) = 5t. It evaporates at 0.5 gal per min: E(t) = 0.5t. Write W(t) for the water in the tank.","a": "W(t) = 4.5t","lvl": 2,"part": "a","steps": ["Water in the tank = water in − water out.","W(t) = 5t − 0.5t. Combine like terms."]},{"id": "AlgI.17-06","std": "Alg I.17","q": "T(h) = 70 + 2h gives temperature after h hours. S(T) = 3T − 50 gives sales at temperature T. Find S(T(5)).","a": "190","lvl": 3,"part": "b","steps": ["Inside first: T(5) = 70 + 2(5) = 80.","Now find S(80) = 3(80) − 50."]},{"id": "AlgI.17-07","std": "Alg I.17","q": "f(x) = x − 4 and g(x) = 3x. Write f(g(x)).","a": "3x − 4","lvl": 2,"part": "b","steps": ["f(g(x)) means g(x) goes into f.","f takes 4 away from whatever goes in. Here 3x goes in."]},{"id": "AlgI.17-08","std": "Alg I.17","q": "f(x) = x + 1 and g(x) = x − 1. Find f(x) · g(x).","a": "x² − 1","lvl": 2,"part": "a","steps": ["Multiply: (x + 1)(x − 1).","That's x² − x + x − 1. Combine the middle terms."]},{"id": "AlgI.18-01","std": "Alg I.18","q": "Solve: y = x² and y = x + 2","a": "(2, 4) and (−1, 1)","lvl": 2,"steps": ["Both equal y, so set them equal: x² = x + 2.","Move it all to one side: x² − x − 2 = 0. Factor: (x − 2)(x + 1) = 0.","Find each x, then find y with y = x + 2."]},{"id": "AlgI.18-02","std": "Alg I.18","q": "Solve: y = x² − 1 and y = 3","a": "(2, 3) and (−2, 3)","lvl": 1,"steps": ["Set them equal: x² − 1 = 3.","Add 1: x² = 4. Take the square root, ±.","Write both points. y is 3 for both."]},{"id": "AlgI.18-03","std": "Alg I.18","q": "How many solutions can a system of a line and a parabola have?","a": "0, 1 or 2","lvl": 1,"also": ["0, 1, or 2"],"steps": ["Sketch a parabola and a line. Can the line miss it?","Can it touch at one point? Cross at two? Can it ever cross at three?"]},{"id": "AlgI.18-04","std": "Alg I.18","q": "Solve: y = x² + 1 and y = 2x","a": "(1, 2)","lvl": 3,"steps": ["Set them equal: x² + 1 = 2x.","Move it all to one side: x² − 2x + 1 = 0. That's (x − 1)² = 0.","Find x, then y = 2x."]},{"id": "AlgI.18-05","std": "Alg I.18","q": "Does y = x² + 3 meet y = 1?","a": "No (x² + 3 is always at least 3)","lvl": 2,"also": ["no"],"steps": ["x² is never negative, so x² + 3 is always at least 3.","Can it ever equal 1?"]},{"id": "AlgI.18-06","std": "Alg I.18","q": "Solve: y = x² − 4x and y = −4","a": "(2, −4)","lvl": 2,"steps": ["Set them equal: x² − 4x = −4.","Add 4: x² − 4x + 4 = 0. That's (x − 2)² = 0.","Find x. y is −4."]},{"id": "AlgI.19-01","std": "Alg I.19","q": "The graphs of y = 2x + 1 and y = 7 cross at x = 3. What does x = 3 solve?","a": "2x + 1 = 7","lvl": 1,"steps": ["Where the graphs cross, both have the same y.","So 2x + 1 equals what? Write that equation."]},{"id": "AlgI.19-02","std": "Alg I.19","q": "Use a table: for which whole x is 2^x = x + 2? Try x = 0, 1, 2, 3.","a": "x = 2","lvl": 2,"steps": ["Try each x. x = 0: 2⁰ = 1 and 0 + 2 = 2. Not equal.","x = 1: 2¹ = 2 and 1 + 2 = 3. Not equal.","Keep going with x = 2 and x = 3. Where are they equal?"]},{"id": "AlgI.19-03","std": "Alg I.19","q": "f(x) = x² and g(x) = 9. Where do the graphs meet? What equation does that solve?","a": "x = 3 and x = −3; x² = 9","lvl": 2,"also": ["±3"],"steps": ["They meet where x² = 9.","What numbers squared are 9? There are two."]},{"id": "AlgI.19-04","std": "Alg I.19","q": "Graphs of y = |x − 1| and y = 3 cross at what x-values?","a": "x = 4 and x = −2","lvl": 2,"also": ["4, −2"],"steps": ["Set |x − 1| = 3. So x − 1 = 3 or x − 1 = −3.","Add 1 to each."]},{"id": "AlgI.19-05","std": "Alg I.19","q": "Why are the x-coordinates where y = f(x) and y = g(x) cross the solutions of f(x) = g(x)?","a": "At those x-values the two outputs are equal","lvl": 2,"steps": ["Where the graphs cross, the points have the same x and the same y.","Same y means f(x) and g(x) are what?"]},{"id": "AlgI.19-06","std": "Alg I.19","q": "Estimate the solution to 2^x = 5 between two whole numbers.","a": "Between 2 and 3","lvl": 3,"also": ["2 and 3"],"steps": ["Try whole numbers: 2² = 4 and 2³ = 8.","5 is between 4 and 8. So x is between which two numbers?"]},{"id": "AlgI.20-01","std": "Alg I.20","q": "Is (1, 1) a solution of y > 2x − 3?","a": "Yes (1 > −1)","lvl": 1,"also": ["yes"],"steps": ["Put (1, 1) in: is 1 > 2(1) − 3?","2(1) − 3 = −1. Is 1 > −1?"]},{"id": "AlgI.20-02","std": "Alg I.20","q": "For y < x + 2, is the boundary line solid or dashed?","a": "Dashed","lvl": 1,"choices": ["Solid","Dashed"],"steps": ["Solid means points on the line count. Dashed means they don't.","Does < include the line?"]},{"id": "AlgI.20-03","std": "Alg I.20","q": "For y ≥ −x + 4, do you shade above or below the line?","a": "Above","lvl": 1,"choices": ["Above","Below"],"steps": ["y ≥ means y is bigger than the line.","Bigger y values are higher up. Above or below?"]},{"id": "AlgI.20-04","std": "Alg I.20","q": "Is (0, 0) a solution of 3x + 2y ≥ 6?","a": "No","lvl": 2,"choices": ["Yes","No"],"steps": ["Put (0, 0) in: 3(0) + 2(0) ≥ 6.","Is 0 ≥ 6?"]},{"id": "AlgI.20-05","std": "Alg I.20","q": "Is (2, 3) in the solution of y > x and y < 5?","a": "Yes","lvl": 2,"choices": ["Yes","No"],"steps": ["Check y > x: is 3 > 2?","Check y < 5: is 3 < 5? Both have to be true."]},{"id": "AlgI.20-06","std": "Alg I.20","q": "Write the inequality: boundary y = 2x + 1, dashed, shaded below.","a": "y < 2x + 1","lvl": 2,"steps": ["Dashed means < or >, not ≤ or ≥.","Shaded below means y is less than the line."]},{"id": "AlgI.20-07","std": "Alg I.20","q": "Is (4, 0) a solution of x + y ≤ 3 and y ≥ 0?","a": "No (4 + 0 is more than 3)","lvl": 2,"also": ["no"],"steps": ["Check x + y ≤ 3: 4 + 0 = 4. Is 4 ≤ 3?","Both have to be true. Is it?"]},{"id": "AlgI.21-01","std": "Alg I.21","q": "f(x) = x² + 3. g has a minimum of 1 on its graph. Which has the smaller minimum?","a": "g","lvl": 2,"steps": ["x² is at least 0, so the minimum of f(x) = x² + 3 is 3.","g's minimum is 1. Which is smaller?"]},{"id": "AlgI.21-02","std": "Alg I.21","q": "f(x) = 2(3)^x. Table for g: x 0, 1, 2 and y 2, 5, 8. Which grows faster as x increases?","a": "f","lvl": 2,"also": ["f(x)"],"steps": ["f: 2, 6, 18. It multiplies by 3 each time.","g: 2, 5, 8. It adds 3 each time. Which grows faster as x gets big?"]},{"id": "AlgI.21-03","std": "Alg I.21","q": "f(x) = −(x − 2)² + 6. g(x) has a maximum of 9. Which has the greater maximum?","a": "g","lvl": 2,"steps": ["−(x − 2)² is never more than 0, so f's maximum is 6.","g's maximum is 9. Which is greater?"]},{"id": "AlgI.21-04","std": "Alg I.21","q": "f(x) = |x| + 1 and g(x) = 2x + 1. What is the same about them at x = 0?","a": "Both equal 1 (same y-intercept)","lvl": 1,"also": ["1"],"steps": ["Find f(0) = |0| + 1 and g(0) = 2(0) + 1.","Both are the same number. Where on the graph is x = 0?"]},{"id": "AlgI.21-05","std": "Alg I.21","q": "f(x) = 3x + 2. g goes through (0, 4) and (2, 8). Which has the greater slope?","a": "f (3 vs 2)","lvl": 1,"also": ["f"],"steps": ["f(x) = 3x + 2 has slope 3.","g's slope is {8 − 4/2 − 0}. Find it and compare."]},{"id": "AlgI.21-06","std": "Alg I.21","q": "f(x) = x² − 4 has zeros at ±2. g(x) = (x − 1)(x + 5). Which has the zero farther from 0?","a": "g (at x = −5)","lvl": 2,"also": ["g"],"steps": ["f has zeros at 2 and −2.","For g, set x − 1 = 0 and x + 5 = 0. Its zeros are 1 and −5.","Which zero is the farthest from 0?"]},{"id": "AlgI.22-01","std": "Alg I.22","q": "Find the next term: 3, 7, 11, 15, …","a": "19","lvl": 1,"part": "a","steps": ["Find the difference: 7 − 3 = 4 and 11 − 7 = 4.","Add 4 to the last term."]},{"id": "AlgI.22-02","std": "Alg I.22","q": "Write an explicit formula: 3, 7, 11, 15, …","a": "aₙ = 4n − 1","lvl": 2,"part": "a","also": ["4n − 1"],"steps": ["It starts at 3 and adds 4 each time.","aₙ = 3 + 4(n − 1). Distribute and combine."]},{"id": "AlgI.22-03","std": "Alg I.22","q": "Find the next term: 2, 6, 18, 54, …","a": "162","lvl": 1,"part": "a","steps": ["Divide: 6 ÷ 2 = 3 and 18 ÷ 6 = 3. It multiplies by 3.","Multiply the last term by 3."]},{"id": "AlgI.22-04","std": "Alg I.22","q": "Write an explicit formula: 2, 6, 18, 54, …","a": "aₙ = 2(3)^{n − 1}","lvl": 2,"part": "a","also": ["2(3)^(n−1)","2·3^(n−1)"],"steps": ["It starts at 2 and multiplies by 3 each time.","Use aₙ = a₁ · r^{n − 1}. Put in a₁ = 2 and r = 3."]},{"id": "AlgI.22-05","std": "Alg I.22","q": "Write a recursive formula: 5, 8, 11, 14, …","a": "a₁ = 5, aₙ = aₙ₋₁ + 3","lvl": 2,"part": "a","also": ["a_n = a_(n−1) + 3"],"steps": ["A recursive formula gives the first term, then how to get each term from the one before.","The first term is 5. Each term adds 3 to aₙ₋₁."]},{"id": "AlgI.22-06","std": "Alg I.22","q": "Write a recursive formula: 80, 40, 20, 10, …","a": "a₁ = 80, aₙ = {1/2}aₙ₋₁","lvl": 2,"part": "a","also": ["a_n = 0.5a_(n−1)"],"steps": ["40 ÷ 80 = {1/2}. Each term is half of the one before.","The first term is 80. Each term is {1/2} times aₙ₋₁."]},{"id": "AlgI.22-07","std": "Alg I.22","q": "Find the 20th term of 3, 7, 11, 15, …","a": "79","lvl": 3,"part": "a","steps": ["It starts at 3 and adds 4, so aₙ = 4n − 1.","Put in n = 20: 4(20) − 1."]},{"id": "AlgI.22-08","std": "Alg I.22","q": "Is an arithmetic sequence linear or exponential?","a": "Linear","lvl": 1,"part": "a","choices": ["Linear","Exponential"],"steps": ["An arithmetic sequence adds the same amount each time.","Adding the same amount makes a straight line. Linear or exponential?"]},{"id": "AlgI.22-09","std": "Alg I.22","q": "What is the domain of a sequence?","a": "Whole numbers 1, 2, 3, … (a subset of the integers)","lvl": 2,"steps": ["A sequence has a 1st term, a 2nd term, a 3rd term and so on.","What kind of numbers count the terms?"]},{"id": "AlgI.23-01","std": "Alg I.23","q": "How does y = x² + 5 compare to y = x²?","a": "It shifts up 5","lvl": 1,"also": ["up 5"],"steps": ["Adding outside the x² moves the graph up or down.","+5 moves it which way, and how far?"]},{"id": "AlgI.23-02","std": "Alg I.23","q": "How does y = (x − 3)² compare to y = x²?","a": "It shifts right 3","lvl": 1,"also": ["right 3"],"steps": ["A change inside with x moves the graph left or right.","Where is x − 3 = 0? That's where the vertex moves to."]},{"id": "AlgI.23-03","std": "Alg I.23","q": "How does y = |x + 4| compare to y = |x|?","a": "It shifts left 4","lvl": 1,"also": ["left 4"],"steps": ["A change inside with x moves the graph left or right.","Where is x + 4 = 0? That's where the vertex moves to."]},{"id": "AlgI.23-04","std": "Alg I.23","q": "How does y = 3x² compare to y = x²?","a": "It is a vertical stretch by 3 (narrower)","lvl": 2,"also": ["stretch","narrower"],"steps": ["Multiplying by 3 makes every y value 3 times as big.","Does that make the graph narrower or wider?"]},{"id": "AlgI.23-05","std": "Alg I.23","q": "How does y = −x² compare to y = x²?","a": "It is reflected over the x-axis","lvl": 2,"also": ["reflection over the x-axis","flipped"],"steps": ["The minus sign makes every y value the opposite.","Points above the x-axis flip below it. What is that move called?"]},{"id": "AlgI.23-06","std": "Alg I.23","q": "f(x) = x². g(x) is the graph shifted down 2 and right 1. Write g(x).","a": "g(x) = (x − 1)² − 2","lvl": 2,"steps": ["Right 1: replace x with x − 1, so (x − 1)².","Down 2: subtract 2 at the end."]},{"id": "AlgI.23-07","std": "Alg I.23","q": "g(x) = f(x) + k. g is f moved down 6. Find k.","a": "k = −6","lvl": 1,"steps": ["Adding k moves the graph up or down.","Down 6 means k is what?"]},{"id": "AlgI.23-08","std": "Alg I.23","q": "f(x) = 2^x. What is g(x) = 2^x − 3?","a": "f shifted down 3","lvl": 2,"also": ["down 3"],"steps": ["The − 3 is outside the 2^{x}.","Subtracting outside moves the graph which way, and how far?"]},{"id": "AlgI.23-09","std": "Alg I.23","q": "How does y = {1/2}|x| compare to y = |x|?","a": "Vertical shrink by {1/2} (wider)","lvl": 2,"also": ["wider","shrink"],"steps": ["Multiplying by {1/2} makes every y value half as big.","Does that make the graph narrower or wider?"]},{"id": "AlgI.24-01","std": "Alg I.24","q": "A table goes 4, 8, 12, 16. Linear or exponential?","a": "Linear (adds 4)","lvl": 1,"part": "a","also": ["linear"],"steps": ["Find the change: 8 − 4, 12 − 8, 16 − 12.","Adding the same each time is linear. Multiplying the same each time is exponential."]},{"id": "AlgI.24-02","std": "Alg I.24","q": "A table goes 4, 8, 16, 32. Linear or exponential?","a": "Exponential (times 2)","lvl": 1,"part": "a","also": ["exponential"],"steps": ["Is it adding the same amount, or multiplying by the same number?","8 ÷ 4 = 2 and 16 ÷ 8 = 2. What kind of growth is that?"]},{"id": "AlgI.24-03","std": "Alg I.24","q": "A town grows by 300 people each year. Linear or exponential?","a": "Linear","lvl": 1,"part": "b","choices": ["Linear","Exponential"],"steps": ["It grows by 300 each year: the same amount added.","Adding the same amount: linear or exponential?"]},{"id": "AlgI.24-04","std": "Alg I.24","q": "A town grows by 3% each year. Linear or exponential?","a": "Exponential","lvl": 1,"part": "c","choices": ["Linear","Exponential"],"steps": ["It grows by 3% each year: times 1.03 each time.","Multiplying by the same number: linear or exponential?"]},{"id": "AlgI.24-05","std": "Alg I.24","q": "Write a function: you start with §50 and add §15 a week.","a": "y = 15x + 50","lvl": 2,"part": "b","steps": ["It starts at 50 and adds 15 each week.","Linear: y = (rate)x + (start)."]},{"id": "AlgI.24-06","std": "Alg I.24","q": "Write a function: a §900 laptop loses 20% of its value each year.","a": "y = 900(0.8)^x","lvl": 2,"part": "c","steps": ["Losing 20% means you keep 80%: 1 − 0.2 = 0.8.","Exponential: y = (start)(factor)^{x}."]},{"id": "AlgI.24-07","std": "Alg I.24","q": "Bacteria start at 100 and triple every hour. Write a function.","a": "y = 100(3)^x","lvl": 2,"part": "c","steps": ["It starts at 100. Tripling means times 3 each hour.","Exponential: y = (start)(factor)^{x}."]},{"id": "AlgI.24-08","std": "Alg I.24","q": "Over equal intervals, an exponential function grows by equal ___.","a": "Factors","lvl": 2,"part": "a","choices": ["Differences","Factors"],"steps": ["Linear adds the same amount each time: equal differences.","Exponential multiplies by the same number each time. What is that called?"]},{"id": "AlgI.25-01","std": "Alg I.25","q": "Write the linear function through (0, 2) and (3, 14).","a": "y = 4x + 2","lvl": 1,"steps": ["Slope = {14 − 2/3 − 0} = {12/3}.","(0, 2) is the y-intercept. Write y = mx + b."]},{"id": "AlgI.25-02","std": "Alg I.25","q": "Write the exponential function through (0, 5) and (1, 15).","a": "y = 5(3)^x","lvl": 1,"steps": ["At x = 0, y = 5. That's the start, a.","From x = 0 to 1, y goes from 5 to 15: times 3. Write y = a(b)^{x}."]},{"id": "AlgI.25-03","std": "Alg I.25","q": "Write the exponential function through (0, 64) and (2, 16).","a": "y = 64({1/2})^x","lvl": 2,"also": ["y = 64(0.5)^x"],"steps": ["At x = 0, y = 64. That's the start, a.","From x = 0 to 2, y goes from 64 to 16. That's times {1/4} over 2 steps.","Each step multiplies by b, and b × b = {1/4}. Find b."]},{"id": "AlgI.25-04","std": "Alg I.25","q": "Write the linear function through (2, 9) and (6, 21).","a": "y = 3x + 3","lvl": 2,"steps": ["Slope = {21 − 9/6 − 2} = {12/4}.","Use y = mx + b with (2, 9): 9 = 3(2) + b. Solve for b."]},{"id": "AlgI.25-05","std": "Alg I.25","q": "Write the exponential function through (1, 6) and (2, 18).","a": "y = 2(3)^x","lvl": 3,"steps": ["From x = 1 to 2, y goes from 6 to 18: times 3. So b = 3.","Work back to x = 0: 6 ÷ 3 is the start, a. Write y = a(b)^{x}."]},{"id": "AlgI.25-06","std": "Alg I.25","q": "A table: x 0, 1, 2, 3 and y 3, 6, 12, 24. Write the function.","a": "y = 3(2)^x","lvl": 2,"steps": ["At x = 0, y = 3. That's the start.","Each y doubles: 3, 6, 12, 24. Write y = a(b)^{x}."]},{"id": "AlgI.25-07","std": "Alg I.25","q": "A table: x 0, 1, 2, 3 and y 10, 7, 4, 1. Write the function.","a": "y = −3x + 10","lvl": 2,"steps": ["At x = 0, y = 10. That's the start.","Each y goes down 3: 10, 7, 4, 1. Write y = mx + b."]},{"id": "AlgI.26-01","std": "Alg I.26","q": "Compare y = 2^x and y = 10x at x = 6.","a": "2^6 = 64 vs 10(6) = 60, so 2^x is bigger","lvl": 2,"also": ["2^x"],"steps": ["2⁶ = 2 × 2 × 2 × 2 × 2 × 2.","10x at x = 6 is 10 × 6. Compare the two."]},{"id": "AlgI.26-02","std": "Alg I.26","q": "At x = 5, which is bigger: y = 2^x or y = 10x?","a": "10x (50 vs 32)","lvl": 1,"also": ["10x"],"steps": ["2⁵ = 2 × 2 × 2 × 2 × 2 = 32.","Find 10(5) and compare."]},{"id": "AlgI.26-03","std": "Alg I.26","q": "Which eventually grows larger: y = 100x or y = 1.1^x?","a": "y = 1.1^x","lvl": 2,"also": ["1.1^x","exponential"],"steps": ["Exponential growth multiplies. Linear growth adds the same amount.","Over a long time, which one wins, even if it starts slower?"]},{"id": "AlgI.26-04","std": "Alg I.26","q": "Which is larger at x = 10: y = x² or y = 2^x?","a": "2^x (1,024 vs 100)","lvl": 2,"also": ["2^x"],"steps": ["x² at x = 10 is 10 × 10.","Find 2¹⁰ by doubling 2 ten times. Compare."]},{"id": "AlgI.26-05","std": "Alg I.26","q": "Job A pays §1,000 a day. Job B pays 1 cent on day 1 and doubles each day. On which day does Job B's daily pay first pass Job A's?","a": "Day 18","lvl": 3,"also": ["18"],"steps": ["On day n, Job B pays 0.01 × 2^{n − 1} dollars.","You need 2^{n − 1} to pass 100,000. Try 2¹⁶ = 65,536 and 2¹⁷ = 131,072.","Which power passes 100,000? Then add 1 to get the day."]},{"id": "AlgI.26-06","std": "Alg I.26","q": "Can a linear function with a large slope stay above an increasing exponential function forever?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["An exponential multiplies each step. A line only adds.","Eventually, does multiplying always beat adding?"]},{"id": "AlgI.27-01","std": "Alg I.27","q": "In y = 25x + 150, where y is total savings after x weeks, what does 150 mean?","a": "§150 saved at the start","lvl": 1,"also": ["starting amount"],"steps": ["Put x = 0 for week 0: y = 25(0) + 150.","So 150 is the savings when?"]},{"id": "AlgI.27-02","std": "Alg I.27","q": "In y = 25x + 150 (savings), what does 25 mean?","a": "§25 saved each week","lvl": 1,"steps": ["25 is multiplied by x, the number of weeks.","So each week adds how much?"]},{"id": "AlgI.27-03","std": "Alg I.27","q": "In y = 3,000(1.04)^t for a town's population, what does 1.04 mean?","a": "The population grows 4% each year","lvl": 1,"also": ["4% growth"],"steps": ["1.04 = 1 + 0.04. It's the growth factor each year.","Write 0.04 as a percent."]},{"id": "AlgI.27-04","std": "Alg I.27","q": "In y = 3,000(1.04)^t, what does 3,000 mean?","a": "The starting population","lvl": 1,"steps": ["Put t = 0: 3,000(1.04)⁰ = 3,000 × 1.","So 3,000 is the population when?"]},{"id": "AlgI.27-05","std": "Alg I.27","q": "In y = 80(0.9)^t for a medicine in the body (mg), what percent leaves each hour?","a": "10%","lvl": 2,"also": ["10"],"steps": ["0.9 means 90% stays each hour.","What percent leaves? 100% − 90%."]},{"id": "AlgI.27-06","std": "Alg I.27","q": "In y = −12x + 300 for fuel in a tank, what does −12 mean?","a": "The tank loses 12 units of fuel each hour (or each unit of x)","lvl": 2,"steps": ["−12 is multiplied by x. It's the rate of change.","Negative means the fuel goes down. By how much for each unit of x?"]},{"id": "AlgI.28-01","std": "Alg I.28","q": "y = −(x − 4)² + 9. What is the maximum?","a": "9","lvl": 1,"steps": ["−(x − 4)² is never more than 0.","So the biggest y can be is 0 + 9. That happens when x = 4."]},{"id": "AlgI.28-02","std": "Alg I.28","q": "y = (x − 1)(x − 5). What are the x-intercepts?","a": "x = 1 and x = 5","lvl": 1,"also": ["1, 5","(1, 0) and (5, 0)"],"steps": ["x-intercepts are where y = 0: (x − 1)(x − 5) = 0.","Set each factor equal to 0."]},{"id": "AlgI.28-03","std": "Alg I.28","q": "y = x² − 6x + 8. What is the y-intercept?","a": "(0, 8)","lvl": 1,"also": ["8"],"steps": ["The y-intercept is where x = 0.","Put x = 0 in: 0² − 6(0) + 8. Write it as a point."]},{"id": "AlgI.28-04","std": "Alg I.28","q": "y = (x − 3)² − 4. On what interval is it decreasing?","a": "x < 3","lvl": 2,"steps": ["The vertex is (3, −4) and the graph opens up.","It goes down until it reaches the vertex. Which x-values are left of 3?"]},{"id": "AlgI.28-05","std": "Alg I.28","q": "y = 2^x. What happens as x gets very negative?","a": "y gets close to 0","lvl": 2,"also": ["approaches 0"],"steps": ["Try x = −1, −2, −3: 2^{−1} = {1/2}, 2^{−2} = {1/4}, 2^{−3} = {1/8}.","The values get smaller but stay positive. What do they get close to?"]},{"id": "AlgI.28-06","std": "Alg I.28","q": "A ball's height h(t) = −16t² + 32t + 48. When is it highest, and how high?","a": "At t = 1 s, 64 ft","lvl": 3,"also": ["(1, 64)"],"steps": ["The top is at the vertex: t = {−b/2a} = {−32/2(−16)}.","That gives t = 1. Put it in: h(1) = −16 + 32 + 48."]},{"id": "AlgI.28-07","std": "Alg I.28","q": "Where is y = |x + 2| − 3 at its minimum?","a": "(−2, −3)","lvl": 2,"steps": ["|x + 2| is smallest, 0, when x = −2.","Then y = 0 − 3. Write the point."]},{"id": "AlgI.28-08","std": "Alg I.28","q": "y = −2x + 6. Where is it positive?","a": "x < 3","lvl": 2,"steps": ["Positive means y > 0: −2x + 6 > 0.","Subtract 6: −2x > −6. Divide by −2 and flip the sign."]},{"id": "AlgI.29-01","std": "Alg I.29","q": "f(x) = x². Find the average rate of change from x = 1 to x = 4.","a": "5","lvl": 1,"steps": ["Average rate of change = {f(4) − f(1)/4 − 1}.","f(4) = 16 and f(1) = 1. Subtract the tops, subtract the bottoms, then divide."]},{"id": "AlgI.29-02","std": "Alg I.29","q": "f(x) = 2^x. Find the average rate of change from x = 0 to x = 3.","a": "2{1/3}","lvl": 2,"also": ["2.33"],"steps": ["Average rate of change = {f(3) − f(0)/3 − 0}.","f(3) = 2³ = 8 and f(0) = 2⁰ = 1.","Subtract, divide by 3, and write it as a mixed number."]},{"id": "AlgI.29-03","std": "Alg I.29","q": "A car is 30 miles away at 1 h and 150 miles away at 3 h. What is its average rate of change?","a": "60 miles per hour","lvl": 1,"also": ["60"],"steps": ["Rate = {change in distance/change in time}.","That's {150 − 30/3 − 1}. Find the top and bottom, then divide."]},{"id": "AlgI.29-04","std": "Alg I.29","q": "f(x) = |x|. Find the average rate of change from x = −4 to x = 2.","a": "−{1/3}","lvl": 2,"steps": ["Average rate of change = {f(2) − f(−4)/2 − (−4)}.","f(2) = |2| = 2 and f(−4) = |−4| = 4.","Top: 2 − 4. Bottom: 2 + 4. Divide and simplify."]},{"id": "AlgI.29-05","std": "Alg I.29","q": "Table: x 0, 2, 4 and y 5, 13, 37. Find the average rate of change from 2 to 4.","a": "12","lvl": 2,"steps": ["Average rate of change = {37 − 13/4 − 2}.","Find the top and bottom, then divide."]},{"id": "AlgI.29-06","std": "Alg I.29","q": "f(x) = −x² + 10. Find the average rate of change from x = 0 to x = 3.","a": "−3","lvl": 2,"steps": ["Average rate of change = {f(3) − f(0)/3 − 0}.","f(3) = −9 + 10 = 1 and f(0) = 10.","Subtract, then divide by 3."]},{"id": "AlgI.29-07","std": "Alg I.29","q": "h(t) = −16t² + 64t. Find the average rate of change from t = 1 to t = 3.","a": "0","lvl": 3,"steps": ["h(1) = −16 + 64 = 48 and h(3) = −144 + 192 = 48.","Average rate of change = {48 − 48/3 − 1}."]},{"id": "AlgI.30-01","std": "Alg I.30","q": "Graph y = x² − 4. What are the x-intercepts and the minimum?","a": "x = ±2; minimum (0, −4)","lvl": 2,"part": "a","also": ["±2"],"steps": ["x-intercepts: set x² − 4 = 0, so x² = 4.","Take the square root, ±.","The lowest point is at x = 0. Find y there."]},{"id": "AlgI.30-02","std": "Alg I.30","q": "y = −x² + 2x + 3. Find the vertex.","a": "(1, 4)","lvl": 2,"part": "a","steps": ["The vertex is at x = {−b/2a} = {−2/2(−1)}.","That's x = 1. Put it in: y = −1 + 2 + 3."]},{"id": "AlgI.30-03","std": "Alg I.30","q": "Find the x- and y-intercepts of y = 3x − 6.","a": "x-intercept (2, 0), y-intercept (0, −6)","lvl": 1,"part": "a","steps": ["x-intercept: set y = 0. Solve 0 = 3x − 6.","y-intercept: set x = 0. Find y = 3(0) − 6. Write both as points."]},{"id": "AlgI.30-04","std": "Alg I.30","q": "y = |x − 2| + 1. Where is the vertex?","a": "(2, 1)","lvl": 1,"part": "b","steps": ["|x − 2| is smallest, 0, when x = 2.","Then y = 0 + 1. Write the point."]},{"id": "AlgI.30-05","std": "Alg I.30","q": "A step function: parking costs §5 for each hour or part of an hour. What do 2.5 hours cost?","a": "§15","lvl": 2,"part": "b","also": ["15"],"steps": ["Part of an hour counts as a whole hour, so 2.5 hours counts as 3 hours.","Each hour is §5. Multiply."]},{"id": "AlgI.30-06","std": "Alg I.30","q": "f(x) = x + 1 when x < 0, and f(x) = 2x when x ≥ 0. Find f(−3) and f(3).","a": "f(−3) = −2, f(3) = 6","lvl": 2,"part": "b","also": ["−2 and 6"],"steps": ["−3 < 0, so use x + 1: f(−3) = −3 + 1.","3 ≥ 0, so use 2x: f(3) = 2(3)."]},{"id": "AlgI.30-07","std": "Alg I.30","q": "y = 3(2)^x. What is the y-intercept?","a": "(0, 3)","lvl": 1,"part": "c","also": ["3"],"steps": ["The y-intercept is at x = 0: y = 3(2)⁰.","Anything to the 0 power is 1. Write the point."]},{"id": "AlgI.30-08","std": "Alg I.30","q": "y = 5({1/2})^x. As x gets large, what happens to y?","a": "y gets close to 0","lvl": 2,"part": "c","also": ["approaches 0"],"steps": ["Try x = 1, 2, 3: y = 2.5, then 1.25, then 0.625.","y keeps halving but stays positive. What does it get close to?"]},{"id": "AlgI.30-09","std": "Alg I.30","q": "Does y = 4(3)^x have an x-intercept?","a": "No (y is always positive)","lvl": 2,"part": "c","also": ["no"],"steps": ["An x-intercept needs y = 0: 4(3)^{x} = 0.","3^{x} is always positive. Can 4 times a positive number be 0?"]},{"id": "AlgI.31-01","std": "Alg I.31","q": "A rocket's height is h = −16t² + 96t. When does it land?","a": "6 seconds","lvl": 2,"also": ["6","t = 6"],"steps": ["It lands when h = 0: −16t² + 96t = 0.","Factor: −16t(t − 6) = 0. Set each factor to 0.","t = 0 is the launch. What's the other time?"]},{"id": "AlgI.31-02","std": "Alg I.31","q": "You invest §2,000 at 5% growing yearly. Write a model and find the value after 3 years.","a": "y = 2,000(1.05)^t; §2,315.25","lvl": 3,"also": ["§2,315.25","2315.25"],"steps": ["Growing 5% means times 1.05 each year: y = 2,000(1.05)^{t}.","Put t = 3: 1.05³ = 1.157625.","Multiply by 2,000 and round to the cent."]},{"id": "AlgI.31-03","std": "Alg I.31","q": "A gym costs §30 to join and §20 a month. You have §190. Model it and find the months you can pay for.","a": "30 + 20m ≤ 190, 8 months","lvl": 2,"also": ["8"],"steps": ["Join fee plus months: 30 + 20m ≤ 190.","Subtract 30: 20m ≤ 160. Divide by 20."]},{"id": "AlgI.31-04","std": "Alg I.31","q": "A model predicts 1,250.6 people at a game. What should you report?","a": "About 1,251 people (whole people)","lvl": 1,"also": ["1251","1,251"],"steps": ["Can you have 0.6 of a person?","Round to a whole number of people."]},{"id": "AlgI.31-05","std": "Alg I.31","q": "After using a model to predict, what is the next step of the modeling cycle?","a": "Check whether the answer makes sense in the situation and revise if needed","lvl": 2,"also": ["validate","check"],"steps": ["The cycle: make a model, compute, then interpret.","Once you have an answer, what should you check before you report it?"]},{"id": "AlgI.31-06","std": "Alg I.31","q": "A fence costs §12 a foot. A square pen has area 144 ft². How much does the fence cost?","a": "§576","lvl": 3,"also": ["576"],"steps": ["Area of a square = side². side² = 144, so the side is √144 = 12 ft.","The fence goes all the way around: 4 × 12 feet.","Multiply the feet by §12 a foot."]},{"id": "AlgI.32-01","std": "Alg I.32","q": "Of 200 drivers, 40 texted while driving and 12 of them had a crash. 160 did not text and 8 had a crash. Find the crash rate for texters.","a": "30%","lvl": 2,"also": ["0.3","30"],"steps": ["Crash rate for texters = crashes ÷ texters = {12/40}.","Change it to a percent."]},{"id": "AlgI.32-02","std": "Alg I.32","q": "Using the data above, find the crash rate for non-texters.","a": "5%","lvl": 2,"also": ["0.05","5"],"steps": ["Crash rate for non-texters = {8/160}.","Change it to a percent."]},{"id": "AlgI.32-03","std": "Alg I.32","q": "Using the data above, how many times as likely is a crash for texters?","a": "6 times","lvl": 3,"also": ["6"],"steps": ["Texters: 30%. Non-texters: 5%.","How many times as big is 30% as 5%? Divide."]},{"id": "AlgI.32-04","std": "Alg I.32","q": "Of 100 students who sleep less than 7 hours, 45 are often tired. Of 100 who sleep more, 15 are. Does sleep seem related to being tired?","a": "Yes (45% vs 15%)","lvl": 2,"also": ["yes"],"steps": ["Less sleep: 45 of 100 are tired, 45%. More sleep: 15 of 100, 15%.","When the rates are very different, the variables seem related. Are they?"]},{"id": "AlgI.32-05","std": "Alg I.32","q": "Does an association in a two-way table prove that one thing causes the other?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["An association means two things happen together.","Could something else cause both? Does that prove one causes the other?"]},{"id": "AlgI.32-06","std": "Alg I.32","q": "A vaccine group of 500 had 10 sick; a no-vaccine group of 500 had 50 sick. Which group had the lower risk?","a": "The vaccine group (2% vs 10%)","lvl": 2,"also": ["vaccine"],"steps": ["Vaccine: {10/500} = 2%. No vaccine: {50/500}.","Which percent is lower?"]},{"id": "AlgI.33-01","std": "Alg I.33","q": "You want to know if 8th graders who play sports prefer outdoor lunch. Name the two categorical variables.","a": "Plays sports (yes/no) and lunch preference (indoor/outdoor)","lvl": 1,"steps": ["A categorical variable sorts people into groups.","What two group questions does the survey ask each student?"]},{"id": "AlgI.33-02","std": "Alg I.33","q": "In your survey, 70% of athletes and 30% of non-athletes prefer outdoor lunch. Is there an association?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Compare the rates: 70% vs 30%.","A big difference in the rates means there is an association."]},{"id": "AlgI.33-03","std": "Alg I.33","q": "In your survey, 52% of athletes and 50% of non-athletes prefer outdoor lunch. Is there an association?","a": "Little or none (the rates are about the same)","lvl": 2,"also": ["no"],"steps": ["Compare the rates: 52% vs 50%.","Is that a big difference?"]},{"id": "AlgI.33-04","std": "Alg I.33","q": "Why should you survey a random sample for an investigation?","a": "So the results represent the whole group without bias","lvl": 2,"steps": ["A random sample gives everyone the same chance to be picked.","What does that do for how well the results match the whole group?"]},{"id": "AlgI.33-05","std": "Alg I.33","q": "Write one sentence to argue there is an association from 70% vs 30%.","a": "Athletes prefer outdoor lunch much more often (70%) than non-athletes (30%), so the variables seem associated","lvl": 3,"steps": ["Name both groups and both percents in your sentence.","Say which group prefers outdoor lunch more, then say what that suggests."]},{"id": "AlgI.33-06","std": "Alg I.33","q": "What kind of table organizes two categorical variables?","a": "A two-way table","lvl": 1,"also": ["two-way table"],"steps": ["Two categorical variables: rows for one, columns for the other.","What is that kind of table called?"]},{"id": "AlgI.34-01","std": "Alg I.34","q": "Is \"favorite color\" quantitative or categorical?","a": "Categorical","lvl": 1,"choices": ["Quantitative","Categorical"],"steps": ["Quantitative means numbers you can do math with. Categorical means groups or labels.","Is a color a number or a label?"]},{"id": "AlgI.34-02","std": "Alg I.34","q": "Is \"height in inches\" quantitative or categorical?","a": "Quantitative","lvl": 1,"choices": ["Quantitative","Categorical"],"steps": ["Quantitative means numbers you measure or count.","Is height a measured number?"]},{"id": "AlgI.34-03","std": "Alg I.34","q": "Is \"zip code\" quantitative or categorical?","a": "Categorical (you do not do math with zip codes)","lvl": 2,"choices": ["Quantitative","Categorical (you do not do math with zip codes)"],"steps": ["A zip code is written with numbers, but is it a measurement?","Does it make sense to add or average zip codes?"]},{"id": "AlgI.34-04","std": "Alg I.34","q": "Which display fits categorical data: a bar graph or a histogram?","a": "Bar graph","lvl": 1,"choices": ["Bar graph","Histogram"],"steps": ["Bar graphs show counts for each category.","Histograms show ranges of numbers. Which one fits categories?"]},{"id": "AlgI.34-05","std": "Alg I.34","q": "Which display fits two quantitative variables?","a": "Scatter plot","lvl": 1,"choices": ["Scatter plot","Two-way table","Pie chart"],"steps": ["Two quantitative variables means two numbers for each person.","Which display plots (x, y) points?"]},{"id": "AlgI.34-06","std": "Alg I.34","q": "Can you find the mean of categorical data?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["The mean adds the values and divides.","Can you add colors or names?"]},{"id": "AlgI.34-07","std": "Alg I.34","q": "Is \"number of pets\" quantitative or categorical?","a": "Quantitative","lvl": 1,"choices": ["Quantitative","Categorical"],"steps": ["Is the number of pets a count?","Counts are numbers you can do math with."]},{"id": "AlgI.35-01","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. How many students like cats?","a": "45","lvl": 1,"part": "a","steps": ["Add the boys who like cats and the girls who like cats.","20 + 25."]},{"id": "AlgI.35-02","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. What is the joint relative frequency of girls who like dogs?","a": "{1/4}","lvl": 2,"part": "b","also": ["0.25","25%"],"steps": ["Joint relative frequency = one cell ÷ the grand total.","Girls who like dogs: {20/80}. Simplify."]},{"id": "AlgI.35-03","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. What is the marginal relative frequency of boys?","a": "{7/16}","lvl": 2,"part": "b","also": ["0.4375","43.75%"],"steps": ["Marginal relative frequency = a row total ÷ the grand total.","Boys: 20 + 15 = 35. Find {35/80} and simplify."]},{"id": "AlgI.35-04","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Of the boys, what fraction like cats?","a": "{4/7}","lvl": 2,"part": "b","also": ["57%"],"steps": ["Only look at the boys: 20 + 15 = 35.","Boys who like cats ÷ all boys: {20/35}. Simplify."]},{"id": "AlgI.35-05","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Of the girls, what fraction like cats?","a": "{5/9}","lvl": 2,"part": "b","also": ["56%"],"steps": ["Only look at the girls: 25 + 20 = 45.","Girls who like cats ÷ all girls: {25/45}. Simplify."]},{"id": "AlgI.35-06","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Is there a strong association between gender and pet preference?","a": "No (about 57% of boys and 56% of girls like cats)","lvl": 3,"part": "c","also": ["no"],"steps": ["Boys who like cats: {20/35}, about 57%.","Girls who like cats: {25/45}, about 56%.","Are those very different?"]},{"id": "AlgI.35-07","std": "Alg I.35","q": "In a segmented bar graph, each bar adds up to what percent?","a": "100%","lvl": 1,"part": "a","also": ["100"],"steps": ["Each bar shows the parts of one whole group.","All the parts of a whole make what percent?"]},{"id": "AlgI.36-01","std": "Alg I.36","q": "Class A: 12 of 20 passed. Class B: 18 of 30 passed. Combine them. What percent passed overall?","a": "60%","lvl": 2,"part": "a","also": ["60"],"steps": ["Add the passes: 12 + 18. Add the students: 20 + 30.","Divide, then make it a percent."]},{"id": "AlgI.36-02","std": "Alg I.36","q": "School 1: 30 of 50 ride the bus. School 2: 45 of 100 ride the bus. What fraction ride overall?","a": "{1/2}","lvl": 2,"part": "a","also": ["50%"],"steps": ["Add the riders: 30 + 45. Add the students: 50 + 100.","Divide, then simplify."]},{"id": "AlgI.36-03","std": "Alg I.36","q": "Two clubs: Club A has 8 of 10 who like pizza, Club B has 20 of 40. What is the overall percent?","a": "56%","lvl": 2,"part": "a","also": ["56"],"steps": ["Add the pizza fans: 8 + 20. Add the members: 10 + 40.","Find {28/50} and make it a percent."]},{"id": "AlgI.36-04","std": "Alg I.36","q": "Why can combined percents differ from the average of two percents?","a": "The groups have different sizes","lvl": 3,"part": "a","steps": ["Try it: 8 of 10 is 80% and 20 of 40 is 50%. Their average is 65%, but overall it's 56%.","Which group has more people in it?"]},{"id": "AlgI.36-05","std": "Alg I.36","q": "Make a two-way table total: 15 + 25 in row 1 and 10 + 30 in row 2. What is the grand total?","a": "80","lvl": 1,"steps": ["Row 1: 15 + 25 = 40. Row 2: 10 + 30 = 40.","Add the row totals."]},{"id": "AlgI.36-06","std": "Alg I.36","q": "A store tracks 60 morning and 40 evening buyers. 30 morning and 30 evening buyers used coupons. What percent of all buyers used coupons?","a": "60%","lvl": 2,"part": "a","also": ["60"],"steps": ["Coupon users: 30 + 30. All buyers: 60 + 40.","Divide, then make it a percent."]},{"id": "AlgI.37-01","std": "Alg I.37","q": "A number cube is rolled. List the event \"even.\"","a": "{2, 4, 6}","lvl": 1,"steps": ["A number cube has 1 to 6.","Which of those are even?"]},{"id": "AlgI.37-02","std": "Alg I.37","q": "A number cube is rolled. A = even, B = greater than 3. List A and B (both).","a": "{4, 6}","lvl": 2,"steps": ["Even: 2, 4, 6. Greater than 3: 4, 5, 6.","And means it's in both lists."]},{"id": "AlgI.37-03","std": "Alg I.37","q": "A number cube is rolled. A = even, B = greater than 3. List A or B.","a": "{2, 4, 5, 6}","lvl": 2,"steps": ["Even: 2, 4, 6. Greater than 3: 4, 5, 6.","Or means it's in either list. List each number once."]},{"id": "AlgI.37-04","std": "Alg I.37","q": "A number cube is rolled. What is the complement of \"rolling a 1 or 2\"?","a": "{3, 4, 5, 6}","lvl": 1,"steps": ["The complement is everything that is NOT the event.","Start with 1 to 6 and take out 1 and 2."]},{"id": "AlgI.37-05","std": "Alg I.37","q": "P(A) = 0.35. What is P(not A)?","a": "0.65","lvl": 1,"steps": ["P(not A) = 1 − P(A).","1 − 0.35."]},{"id": "AlgI.37-06","std": "Alg I.37","q": "How many outcomes are there for flipping 3 coins?","a": "8","lvl": 1,"steps": ["Each coin has 2 outcomes.","Multiply: 2 × 2 × 2."]},{"id": "AlgI.37-07","std": "Alg I.37","q": "A deck has 52 cards. How many are red or a king?","a": "28","lvl": 3,"steps": ["Red cards: 26. Kings: 4.","2 of the kings are red, so they got counted twice: 26 + 4 − 2."]},{"id": "AlgI.37-08","std": "Alg I.37","q": "An outfit is a shirt (4 choices), pants (3) and shoes (2). How many outfits?","a": "24","lvl": 1,"steps": ["Multiply the number of choices for each part.","4 × 3 × 2."]},{"id": "AlgI.38-01","std": "Alg I.38","q": "You flip a coin and roll a cube. Are the results independent?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Independent means one result doesn't change the chance of the other.","Does the coin change how the cube lands?"]},{"id": "AlgI.38-02","std": "Alg I.38","q": "You draw two cards without putting the first back. Are the draws independent?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["After the first card, the deck has one fewer card.","Does that change the chances for the second draw?"]},{"id": "AlgI.38-03","std": "Alg I.38","q": "P(A) = 0.5, P(B) = 0.4 and P(A and B) = 0.2. Are A and B independent?","a": "Yes (0.5 × 0.4 = 0.2)","lvl": 2,"also": ["yes"],"steps": ["A and B are independent if P(A) × P(B) = P(A and B).","0.5 × 0.4 = ? Compare it with 0.2."]},{"id": "AlgI.38-04","std": "Alg I.38","q": "P(A) = 0.3, P(B) = 0.6 and P(A and B) = 0.25. Are A and B independent?","a": "No (0.3 × 0.6 = 0.18)","lvl": 2,"also": ["no"],"steps": ["A and B are independent if P(A) × P(B) = P(A and B).","0.3 × 0.6 = 0.18. Is that 0.25?"]},{"id": "AlgI.38-05","std": "Alg I.38","q": "Of 100 students, 40 play an instrument and 50 are in 8th grade. 20 are 8th graders who play an instrument. Are the events independent?","a": "Yes (0.4 × 0.5 = 0.2)","lvl": 3,"also": ["yes"],"steps": ["P(instrument) = 0.4, P(8th grade) = 0.5 and P(both) = 0.2.","Check: does 0.4 × 0.5 equal 0.2?"]},{"id": "AlgI.38-06","std": "Alg I.38","q": "A and B are independent with P(A) = 0.2 and P(B) = 0.5. Find P(A and B).","a": "0.1","lvl": 2,"steps": ["Independent: P(A and B) = P(A) × P(B).","0.2 × 0.5."]},{"id": "AlgI.39-01","std": "Alg I.39","q": "Of 80 students, 30 have a dog. 12 of the dog owners also have a cat. Find P(cat | dog).","a": "{2/5}","lvl": 2,"also": ["0.4","40%"],"steps": ["Given dog: only look at the 30 dog owners.","12 of them have a cat. Find {12/30} and simplify."]},{"id": "AlgI.39-02","std": "Alg I.39","q": "P(A and B) = 0.12 and P(B) = 0.4. Find P(A | B).","a": "0.3","lvl": 2,"steps": ["P(A | B) = {P(A and B)/P(B)}.","Find {0.12/0.4}."]},{"id": "AlgI.39-03","std": "Alg I.39","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Find P(likes dogs | girl).","a": "{4/9}","lvl": 2,"steps": ["Given girl: only look at the girls, 25 + 20 = 45.","20 girls like dogs. Find {20/45} and simplify."]},{"id": "AlgI.39-04","std": "Alg I.39","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Find P(girl | likes dogs).","a": "{4/7}","lvl": 3,"steps": ["Given likes dogs: only look at the dog lovers, 15 + 20 = 35.","20 of them are girls. Find {20/35} and simplify."]},{"id": "AlgI.39-05","std": "Alg I.39","q": "A bag has 3 red and 2 blue marbles. You draw one red and don't put it back. What is P(second is red | first was red)?","a": "{1/2}","lvl": 2,"steps": ["After one red is gone, the bag has 2 red and 2 blue.","P(red) = red marbles ÷ all marbles."]},{"id": "AlgI.39-06","std": "Alg I.39","q": "A tree diagram: P(rain) = 0.3, P(late | rain) = 0.5. Find P(rain and late).","a": "0.15","lvl": 2,"steps": ["P(rain and late) = P(rain) × P(late | rain).","0.3 × 0.5."]},{"id": "AlgI.39-07","std": "Alg I.39","q": "Are mutually exclusive events able to happen at the same time?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["Mutually exclusive events share no outcomes.","If they share nothing, can both happen at once?"]},{"id": "AlgI.39-08","std": "Alg I.39","q": "A card is drawn from a standard deck. Are \"heart\" and \"spade\" mutually exclusive?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Can one card be a heart and a spade at the same time?","Mutually exclusive means they can't happen together."]},{"id": "AlgI.40-01","std": "Alg I.40","q": "Explain P(umbrella | rain) in everyday words.","a": "The chance someone carries an umbrella when it is raining","lvl": 1,"steps": ["The bar | means given. Read it as: the chance of an umbrella, given rain.","Say it as a sentence about a rainy day."]},{"id": "AlgI.40-02","std": "Alg I.40","q": "Is the chance of being late higher given there is a snowstorm? Is that conditional probability?","a": "Yes; it is the chance of being late given a snowstorm","lvl": 1,"also": ["yes"],"steps": ["Does a snowstorm make being late more likely?","A chance given a condition is what conditional probability means."]},{"id": "AlgI.40-03","std": "Alg I.40","q": "Does knowing a coin landed heads change the chance the next flip is heads?","a": "No (the flips are independent)","lvl": 1,"also": ["no"],"steps": ["Does a coin remember the last flip?","Independent events don't change each other's chances."]},{"id": "AlgI.40-04","std": "Alg I.40","q": "P(pass | studied) = 0.9 and P(pass | did not study) = 0.5. Are passing and studying independent?","a": "No (the chances are different)","lvl": 2,"also": ["no"],"steps": ["If they were independent, P(pass) would be the same whether you studied or not.","0.9 vs 0.5. Are they the same?"]},{"id": "AlgI.40-05","std": "Alg I.40","q": "Is P(sick | fever) the same as P(fever | sick)? Explain.","a": "No; the first is among people with a fever, the second is among sick people","lvl": 3,"also": ["no"],"steps": ["P(sick | fever): look only at people with a fever.","P(fever | sick): look only at sick people. Are those the same group?"]},{"id": "AlgI.40-06","std": "Alg I.40","q": "Give an example of two independent events in everyday life.","a": "Rolling a die and the weather tomorrow","lvl": 2,"steps": ["Independent means one thing doesn't change the chance of the other.","Think of two things that have nothing to do with each other."]},{"id": "AlgI.41-01","std": "Alg I.41","q": "A number cube is rolled. Given the roll is even, what is the probability it is a 6?","a": "{1/3}","lvl": 1,"steps": ["Given even: only look at 2, 4 and 6.","How many of those are a 6? Out of how many?"]},{"id": "AlgI.41-02","std": "Alg I.41","q": "A number cube is rolled. Given the roll is greater than 2, what is the probability it is even?","a": "{1/2}","lvl": 2,"steps": ["Given greater than 2: only look at 3, 4, 5 and 6.","How many of those are even? Out of 4."]},{"id": "AlgI.41-03","std": "Alg I.41","q": "Of 50 students in band, 20 also play a sport. What is P(sport | band)?","a": "{2/5}","lvl": 1,"also": ["0.4","40%"],"steps": ["Given band: only look at the 50 band students.","20 of them play a sport. Find {20/50} and simplify."]},{"id": "AlgI.41-04","std": "Alg I.41","q": "In P(A | B), which group do you divide by?","a": "The outcomes in B","lvl": 1,"also": ["B"],"steps": ["P(A | B) means the chance of A, given B.","You only look inside B. So what goes on the bottom of the fraction?"]},{"id": "AlgI.41-05","std": "Alg I.41","q": "Two coins are flipped. Given at least one is heads, what is the probability both are heads?","a": "{1/3}","lvl": 3,"steps": ["Two coins can land HH, HT, TH or TT.","Given at least one heads, cross out TT. How many are left?","How many of those are HH?"]},{"id": "AlgI.41-06","std": "Alg I.41","q": "Of 120 people at a game, 75 wore team colors. 45 of those cheered loudly. What fraction of people in team colors cheered loudly?","a": "{3/5}","lvl": 2,"also": ["0.6","60%"],"steps": ["Only look at the 75 in team colors.","45 of them cheered loudly. Find {45/75} and simplify."]}]};
